import React, { useState, useRef, useEffect, useCallback } from 'react';
import { SpotterAgentEmbed } from '@thoughtspot/visual-embed-sdk';
import { THOUGHTSPOT_MODEL_ID, TOP_HEADER_PX } from '../config/thoughtspot';

// ─── Brand tokens ─────────────────────────────────────────────────────────────
const BLUE   = '#2B3CC1';
const NAVY   = '#0F1875';
const BG     = '#F0F2FF';
const BG2    = '#E5E8FA';
const BORDER = 'rgba(43,60,193,0.12)';
const INK2   = '#515962';

// ─── Sample questions ─────────────────────────────────────────────────────────
const SAMPLE_QUESTIONS = [
  { label: 'Units sold by channel',         query: 'units sold by channel' },
  { label: 'Top performing categories',      query: 'top categories by net revenue' },
  { label: 'Inventory by brand',             query: 'quantity on hand by brand' },
  { label: 'Revenue vs last month',          query: 'net revenue this month vs last month' },
  { label: 'Sell-through by category',       query: 'sell through rate by category' },
  { label: 'Products needing restock',       query: 'products with low stock and high sell through rate' },
];

// ─── General company Q&A ──────────────────────────────────────────────────────
const COMPANY_TRIGGERS = [
  /what (does|is) lumira/i,
  /who is lumira/i,
  /tell me about lumira/i,
  /about lumira/i,
  /lumira('s)? (mission|vision|features?|product|platform|offering|story|history)/i,
  /what (can|do) (you|lumira) (do|offer|help)/i,
  /how does lumira work/i,
];

const COMPANY_BRIEF = `**Lumira** is a retail intelligence platform built for modern commerce teams.

We connect your sales, inventory, channel, and supplier data into a single live view — so every team from buying to marketing can make faster, more confident decisions.

**Key capabilities:**
• **Real-time dashboards** — track revenue, sell-through, stock health, and returns across every channel
• **AI-powered Q&A** — ask plain-English questions and get instant charts backed by live data
• **Restock intelligence** — surface low-stock, high-velocity SKUs before you miss a sale
• **Channel analytics** — compare performance across DTC, marketplace, wholesale, and retail

Lumira AI is the conversational layer built into every screen — just ask, and your data answers.`;

function isGeneralQuestion(q: string) {
  return COMPANY_TRIGGERS.some(rx => rx.test(q));
}

// ─── Types ────────────────────────────────────────────────────────────────────
type QuestionKind = 'data' | 'general';

interface Message {
  id:   number;
  type: 'user' | 'ai' | 'loading' | 'text';
  kind?: QuestionKind;   // on answer/loading messages
  text?: string;
}

// ─── Gem icon ─────────────────────────────────────────────────────────────────
function LumiraGem({ size = 48, color = BLUE }: { size?: number; color?: string }) {
  const s = size, cx = s / 2, cy = s / 2, r = s * 0.42;
  const pts = Array.from({ length: 6 }, (_, i) => {
    const a = (Math.PI / 3) * i - Math.PI / 2;
    return [cx + r * Math.cos(a), cy + r * Math.sin(a)] as [number, number];
  });
  const hex     = pts.map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  const topPoly = [...pts.slice(0, 3), [cx, cy] as [number, number]]
    .map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
  return (
    <svg width={s} height={s} viewBox={`0 0 ${s} ${s}`} fill="none">
      <polygon points={hex} stroke={color} strokeWidth="2" fill={`${color}14`} strokeLinejoin="round" />
      <polygon points={topPoly} fill={`${color}30`} strokeLinejoin="round" />
      <line x1={pts[0][0]} y1={pts[0][1]} x2={cx} y2={cy} stroke={color} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[1][0]} y1={pts[1][1]} x2={cx} y2={cy} stroke={color} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[2][0]} y1={pts[2][1]} x2={cx} y2={cy} stroke={color} strokeWidth="1.2" strokeOpacity="0.6" />
      <line x1={pts[0][0]} y1={pts[0][1]} x2={pts[2][0]} y2={pts[2][1]} stroke={color} strokeWidth="1.2" strokeOpacity="0.4" />
    </svg>
  );
}

// ─── Typing dots ──────────────────────────────────────────────────────────────
function TypingDots() {
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 4, padding: '10px 4px' }}>
      {[0, 1, 2].map(i => (
        <div key={i} style={{
          width: 6, height: 6, borderRadius: '50%', backgroundColor: BLUE,
          animation: 'lumiraBounce 1.2s ease-in-out infinite',
          animationDelay: `${i * 0.2}s`, opacity: 0.7,
        }} />
      ))}
      <style>{`
        @keyframes lumiraBounce {
          0%,80%,100% { transform:translateY(0); opacity:0.4; }
          40%          { transform:translateY(-6px); opacity:1; }
        }
      `}</style>
    </div>
  );
}

// ─── Company brief renderer ───────────────────────────────────────────────────
function CompanyBrief({ text }: { text: string }) {
  return (
    <div style={{ fontSize: 13, lineHeight: 1.75, color: NAVY }}>
      {text.split('\n').map((line, i) => {
        if (!line.trim()) return <div key={i} style={{ height: 5 }} />;
        const parts = line.split(/\*\*(.*?)\*\*/g);
        return (
          <div key={i}>
            {parts.map((p, j) => j % 2 === 1 ? <strong key={j}>{p}</strong> : <span key={j}>{p}</span>)}
          </div>
        );
      })}
    </div>
  );
}

// ─── Page ─────────────────────────────────────────────────────────────────────
export default function AskLumiraPage() {
  const [messages, setMessages]     = useState<Message[]>([]);
  const [input, setInput]           = useState('');
  const [isLoading, setIsLoading]   = useState(false);
  const [activeChip, setActiveChip] = useState<string | null>(null);

  const agentRef       = useRef<SpotterAgentEmbed | null>(null);
  const counterRef     = useRef(0);
  const leftScrollRef  = useRef<HTMLDivElement>(null);
  const rightScrollRef = useRef<HTMLDivElement>(null);
  const inputRef       = useRef<HTMLInputElement>(null);

  useEffect(() => {
    agentRef.current = new SpotterAgentEmbed({
      worksheetId: THOUGHTSPOT_MODEL_ID,
      frameParams: { height: '520px', width: '100%' },
    } as any);
  }, []);

  // auto-scroll
  useEffect(() => {
    leftScrollRef.current?.scrollTo({ top: leftScrollRef.current.scrollHeight, behavior: 'smooth' });
    rightScrollRef.current?.scrollTo({ top: rightScrollRef.current.scrollHeight, behavior: 'smooth' });
  }, [messages]);

  const appendViz = useCallback((msgId: number, container: HTMLDivElement) => {
    const slot = document.getElementById(`lumira-viz-${msgId}`);
    if (!slot) return;
    slot.innerHTML = '';
    container.style.width   = '100%';
    container.style.height  = '520px';
    container.style.display = 'block';
    slot.querySelectorAll('iframe').forEach(f => {
      f.style.width = '100%'; f.style.height = '520px';
      f.style.border = 'none'; f.style.display = 'block';
    });
    slot.appendChild(container);
    // style iframes that land inside the appended container
    container.querySelectorAll('iframe').forEach(f => {
      f.style.width = '100%'; f.style.height = '520px';
      f.style.border = 'none'; f.style.display = 'block';
    });
  }, []);

  const send = useCallback(async (query: string) => {
    if (!query.trim() || isLoading || !agentRef.current) return;
    const uid  = ++counterRef.current;
    const aid  = ++counterRef.current;
    const kind: QuestionKind = isGeneralQuestion(query) ? 'general' : 'data';

    setMessages(prev => [
      ...prev,
      { id: uid, type: 'user', text: query },
      { id: aid, type: 'loading', kind },
    ]);
    setIsLoading(true);
    setInput('');

    if (kind === 'general') {
      await new Promise(r => setTimeout(r, 700));
      setIsLoading(false);
      setMessages(prev => prev.map(m =>
        m.id === aid ? { ...m, type: 'text' as const, text: COMPANY_BRIEF } : m
      ));
      return;
    }

    // Data question → viz on left
    const result = await agentRef.current.sendMessage(query);
    setIsLoading(false);
    setMessages(prev => prev.map(m =>
      m.id === aid ? { ...m, type: 'ai' as const } : m
    ));
    if (result && !result.error && result.container) {
      setTimeout(() => appendViz(aid, result.container as HTMLDivElement), 60);
    }
  }, [isLoading, appendViz]);

  const handleChip = (query: string) => { setActiveChip(query); send(query); };
  const handleSubmit = (e: React.FormEvent) => { e.preventDefault(); send(input); };

  // Split messages for each panel
  const rightMessages = messages.filter(m =>
    m.type === 'user' ||
    (m.kind === 'general' && (m.type === 'text' || m.type === 'loading'))
  );
  const leftAnswers = messages.filter(m =>
    m.kind === 'data' && (m.type === 'ai' || m.type === 'loading')
  );
  // Pair each left answer with its preceding user message
  const userMsgs  = messages.filter(m => m.type === 'user');
  const dataAnswerMsgs = leftAnswers; // same order as user data questions

  // Which user msgs were data questions?
  const dataUserMsgs = messages.filter(m => {
    if (m.type !== 'user') return false;
    const myIdx = messages.indexOf(m);
    const next  = messages[myIdx + 1];
    return next?.kind === 'data';
  });

  const hasDataAnswers = leftAnswers.length > 0;

  const PAGE_H = `calc(100vh - ${TOP_HEADER_PX}px)`;

  return (
    <div style={{ display: 'flex', height: PAGE_H, backgroundColor: BG, overflow: 'hidden' }}>

      {/* ══════════════════════════════════════════════════════════════════
          LEFT — hero / data viz answers
         ══════════════════════════════════════════════════════════════════ */}
      <div
        ref={leftScrollRef}
        style={{
          flex: '0 0 68%',
          overflowY: 'auto',
          borderRight: `1px solid ${BORDER}`,
          backgroundColor: hasDataAnswers ? '#FAFBFF' : BG,
          display: 'flex',
          flexDirection: 'column',
        }}
      >
        {!hasDataAnswers ? (
          /* Hero state */
          <div style={{
            flex: 1, display: 'flex', flexDirection: 'column',
            justifyContent: 'center', alignItems: 'center',
            padding: '3rem 4rem', textAlign: 'center',
            position: 'relative', overflow: 'hidden',
          }}>
            {[280, 420, 560].map(d => (
              <div key={d} style={{
                position: 'absolute', width: d, height: d, borderRadius: '50%',
                border: `1px solid rgba(43,60,193,${(0.07 - d * 0.00009).toFixed(3)})`,
                top: '50%', left: '50%', transform: 'translate(-50%,-50%)',
                pointerEvents: 'none',
              }} />
            ))}
            <div style={{ position: 'relative', zIndex: 1, maxWidth: 480 }}>
              <div style={{ marginBottom: '1.5rem', display: 'flex', justifyContent: 'center' }}>
                <LumiraGem size={64} />
              </div>
              <div style={{
                display: 'inline-flex', alignItems: 'center', gap: 6,
                backgroundColor: BLUE, color: '#FFF', borderRadius: 20,
                padding: '4px 14px', fontSize: 10.5, fontWeight: 700,
                letterSpacing: '0.08em', textTransform: 'uppercase', marginBottom: '1.25rem',
              }}>
                <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor">
                  <path d="M12 2l2.4 7.4H22l-6.2 4.5 2.4 7.4L12 17l-6.2 4.3 2.4-7.4L2 9.4h7.6z"/>
                </svg>
                Powered by Lumira AI
              </div>
              <h1 style={{
                fontSize: 'clamp(28px,3vw,40px)', fontWeight: 800, color: NAVY,
                letterSpacing: '-0.03em', margin: '0 0 1rem', lineHeight: 1.1,
              }}>
                Ask Lumira
              </h1>
              <p style={{ fontSize: 14.5, color: INK2, lineHeight: 1.7, margin: '0 0 2rem', maxWidth: 400 }}>
                Ask a data question on the right and your live chart will appear here.
                Or ask anything about Lumira and get an answer in the chat.
              </p>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, justifyContent: 'center' }}>
                {SAMPLE_QUESTIONS.map(q => (
                  <button key={q.query} type="button" onClick={() => handleChip(q.query)} style={{
                    padding: '7px 14px', borderRadius: 20,
                    border: `1px solid ${BORDER}`,
                    backgroundColor: activeChip === q.query ? BLUE : '#FFFFFF',
                    color: activeChip === q.query ? '#FFF' : NAVY,
                    fontSize: 12.5, fontWeight: activeChip === q.query ? 600 : 500,
                    cursor: 'pointer', transition: 'all 0.15s',
                    boxShadow: '0 1px 4px rgba(43,60,193,0.06)',
                  }}>{q.label}</button>
                ))}
              </div>
            </div>
          </div>
        ) : (
          /* Data viz feed */
          <div style={{ padding: '1.5rem 2rem', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            {dataAnswerMsgs.map((msg, i) => (
              <div key={msg.id}>
                {dataUserMsgs[i] && (
                  <div style={{
                    fontSize: 11, fontWeight: 600, color: BLUE,
                    textTransform: 'uppercase', letterSpacing: '0.06em',
                    marginBottom: '0.6rem',
                    display: 'flex', alignItems: 'center', gap: 6,
                  }}>
                    <svg width="10" height="10" viewBox="0 0 24 24" fill="none"
                      stroke={BLUE} strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                      <circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/>
                    </svg>
                    {dataUserMsgs[i].text}
                  </div>
                )}
                <div style={{
                  backgroundColor: '#FFFFFF', border: `1px solid ${BORDER}`,
                  borderRadius: 14, overflow: 'hidden',
                  boxShadow: '0 2px 12px rgba(43,60,193,0.06)',
                }}>
                  {msg.type === 'loading' && (
                    <div style={{ padding: '1.25rem 1.5rem', display: 'flex', alignItems: 'center', gap: 10 }}>
                      <LumiraGem size={18} />
                      <span style={{ fontSize: 13, color: INK2 }}>Generating your chart…</span>
                      <TypingDots />
                    </div>
                  )}
                  {msg.type === 'ai' && (
                    <div id={`lumira-viz-${msg.id}`} style={{ height: 520, width: '100%', overflow: 'hidden' }} />
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* ══════════════════════════════════════════════════════════════════
          RIGHT — chat (user questions + general AI replies)
         ══════════════════════════════════════════════════════════════════ */}
      <div style={{
        flex: '0 0 32%',
        display: 'flex', flexDirection: 'column',
        backgroundColor: '#FFFFFF',
        overflow: 'hidden',
      }}>

        {/* Header */}
        <div style={{
          padding: '1rem 1.25rem',
          borderBottom: `1px solid ${BORDER}`,
          display: 'flex', alignItems: 'center', gap: 10,
          flexShrink: 0,
        }}>
          <LumiraGem size={28} />
          <div>
            <div style={{ fontSize: 14, fontWeight: 700, color: NAVY, letterSpacing: '-0.01em' }}>Lumira AI</div>
            <div style={{ fontSize: 11, color: INK2 }}>Commerce intelligence</div>
          </div>
          <div style={{
            marginLeft: 'auto', width: 8, height: 8, borderRadius: '50%',
            backgroundColor: '#16a34a', boxShadow: '0 0 0 3px rgba(22,163,74,0.20)',
          }} />
        </div>

        {/* Conversation feed */}
        <div
          ref={rightScrollRef}
          style={{
            flex: 1, overflowY: 'auto',
            padding: '1rem',
            display: 'flex', flexDirection: 'column', gap: 10,
            backgroundColor: BG,
          }}
        >
          {rightMessages.length === 0 && (
            <div style={{
              textAlign: 'center', padding: '2rem 1rem',
              color: INK2, fontSize: 13, lineHeight: 1.65,
            }}>
              Ask a data question to see a live chart on the left, or ask anything about Lumira here.
            </div>
          )}

          {rightMessages.map(msg => (
            <div key={msg.id} style={{
              display: 'flex',
              flexDirection: msg.type === 'user' ? 'row-reverse' : 'row',
              alignItems: 'flex-start', gap: 7,
            }}>
              {/* AI avatar */}
              {msg.type !== 'user' && (
                <div style={{
                  width: 24, height: 24, borderRadius: '50%',
                  backgroundColor: BG2, border: `1px solid ${BORDER}`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  flexShrink: 0, marginTop: 2,
                }}>
                  <LumiraGem size={13} />
                </div>
              )}

              {/* Bubble */}
              <div style={{
                maxWidth: '85%',
                backgroundColor: msg.type === 'user' ? BLUE : '#FFFFFF',
                color: msg.type === 'user' ? '#FFF' : NAVY,
                borderRadius: msg.type === 'user' ? '14px 14px 2px 14px' : '14px 14px 14px 2px',
                padding: msg.type === 'loading' ? '10px 12px' : '9px 13px',
                fontSize: 13, lineHeight: 1.5,
                boxShadow: '0 1px 4px rgba(43,60,193,0.08)',
                border: msg.type !== 'user' ? `1px solid ${BORDER}` : 'none',
              }}>
                {msg.type === 'user'    && msg.text}
                {msg.type === 'loading' && <TypingDots />}
                {msg.type === 'text'    && <CompanyBrief text={msg.text ?? ''} />}
              </div>
            </div>
          ))}

          {/* "Chart sent to left" status pills for data questions */}
          {userMsgs.filter((m, i) => {
            const myIdx = messages.indexOf(m);
            const next  = messages[myIdx + 1];
            return next?.kind === 'data' && next?.type === 'ai';
          }).length > 0 && (
            <div style={{ display: 'flex', flexDirection: 'column', gap: 6, marginTop: 4 }}>
              {userMsgs
                .filter(m => {
                  const myIdx = messages.indexOf(m);
                  const next  = messages[myIdx + 1];
                  return next?.kind === 'data' && next?.type === 'ai';
                })
                .map(m => {
                  const myIdx = messages.indexOf(m);
                  const next  = messages[myIdx + 1];
                  return (
                    <div key={`status-${next?.id}`} style={{
                      display: 'flex', alignItems: 'center', gap: 6,
                      padding: '5px 10px', borderRadius: 20,
                      backgroundColor: '#ecfdf5',
                      border: '1px solid rgba(22,163,74,0.25)',
                      alignSelf: 'flex-end',
                      fontSize: 11.5, color: '#15803d', fontWeight: 500,
                    }}>
                      <svg width="10" height="10" viewBox="0 0 24 24" fill="none"
                        stroke="#16a34a" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                        <polyline points="20 6 9 17 4 12"/>
                      </svg>
                      Chart ready ←
                    </div>
                  );
                })}
            </div>
          )}

          {/* Chips */}
          {messages.length > 0 && (
            <div style={{ marginTop: 8 }}>
              <div style={{ fontSize: 11, color: INK2, marginBottom: 6, fontWeight: 500 }}>Try asking:</div>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
                {SAMPLE_QUESTIONS.map(q => (
                  <button key={q.query} type="button" onClick={() => handleChip(q.query)} style={{
                    padding: '5px 11px', borderRadius: 16,
                    border: `1px solid ${BORDER}`, backgroundColor: '#FFFFFF',
                    color: NAVY, fontSize: 11.5, fontWeight: 500,
                    cursor: 'pointer', transition: 'all 0.12s',
                  }}>{q.label}</button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Input */}
        <form onSubmit={handleSubmit} style={{
          padding: '0.75rem 1rem',
          borderTop: `1px solid ${BORDER}`,
          backgroundColor: '#FFFFFF',
          display: 'flex', gap: 8, alignItems: 'center',
          flexShrink: 0,
        }}>
          <input
            ref={inputRef}
            value={input}
            onChange={e => setInput(e.target.value)}
            placeholder={messages.length > 0 ? 'Ask a follow up…' : 'Ask anything…'}
            disabled={isLoading}
            style={{
              flex: 1, padding: '9px 13px', borderRadius: 22,
              border: `1px solid ${BORDER}`,
              fontSize: 13, color: NAVY, backgroundColor: BG,
              outline: 'none', fontFamily: "'Inter', -apple-system, sans-serif",
            }}
          />
          <button
            type="submit"
            disabled={isLoading || !input.trim()}
            style={{
              width: 36, height: 36, borderRadius: '50%',
              backgroundColor: isLoading || !input.trim() ? BG2 : BLUE,
              border: 'none',
              cursor: isLoading || !input.trim() ? 'default' : 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              flexShrink: 0, transition: 'background 0.15s',
            }}
          >
            <svg width="15" height="15" viewBox="0 0 24 24" fill="none"
              stroke={isLoading || !input.trim() ? INK2 : '#FFFFFF'}
              strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <line x1="22" y1="2" x2="11" y2="13"/>
              <polygon points="22 2 15 22 11 13 2 9 22 2"/>
            </svg>
          </button>
        </form>
      </div>
    </div>
  );
}
